-- BEGIN SOURCE 013_durable_async_builds.sql
-- 013_durable_async_builds.sql
-- Idempotent schema additions for M1 Durable Async Builds
-- Verified against infra/postgres/001_control_plane.sql (build_jobs),
-- 010_international_product.sql (project_versions), 012_creator_subscriptions.sql
-- (creator_subscriptions) before being applied. Applied verbatim from the pasted
-- M1 Revision 2 patch -- schema-compatible with the existing tables.

CREATE TABLE IF NOT EXISTS credit_reservations (
    build_id TEXT PRIMARY KEY,
    account_id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    credits_reserved INTEGER NOT NULL CHECK (credits_reserved >= 0),
    estimated_provider_cost_usd NUMERIC(14,6) NOT NULL DEFAULT 0,
    actual_provider_cost_usd NUMERIC(14,6),
    settled_provider_cost_usd NUMERIC(14,6),
    status TEXT NOT NULL CHECK (status IN ('RESERVED', 'SETTLED', 'RELEASED')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    resolved_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS build_requests (
    build_id TEXT PRIMARY KEY REFERENCES credit_reservations(build_id),
    user_id TEXT NOT NULL,
    internal_project_id TEXT NOT NULL,
    prompt TEXT NOT NULL,
    target_markets JSONB NOT NULL DEFAULT '[]'::jsonb,
    branding_visible BOOLEAN,
    white_label_name TEXT,
    rights_evidence JSONB NOT NULL DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Enhance build_jobs with phase, explicit costs, and evidence
ALTER TABLE build_jobs
    ADD COLUMN IF NOT EXISTS phase TEXT NOT NULL DEFAULT 'QUEUED',
    ADD COLUMN IF NOT EXISTS message TEXT,
    ADD COLUMN IF NOT EXISTS result_version_id TEXT,
    ADD COLUMN IF NOT EXISTS actual_provider_cost_usd NUMERIC(14,6),
    ADD COLUMN IF NOT EXISTS estimated_provider_cost_usd NUMERIC(14,6),
    ADD COLUMN IF NOT EXISTS repair_rounds INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS evidence_json JSONB NOT NULL DEFAULT '{}'::jsonb;

-- Ensure project_versions can store the artifact explicitly
ALTER TABLE project_versions
    ADD COLUMN IF NOT EXISTS artifact_key TEXT,
    ADD COLUMN IF NOT EXISTS file_count INTEGER NOT NULL DEFAULT 0;

-- Transactional Outbox for Redis Enqueueing
CREATE TABLE IF NOT EXISTS build_outbox (
    id BIGSERIAL PRIMARY KEY,
    build_id TEXT NOT NULL UNIQUE REFERENCES build_requests(build_id),
    enqueued_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- END SOURCE 013_durable_async_builds.sql

-- BEGIN SOURCE 014_real_running_preview.sql
-- 014_real_running_preview.sql
-- M3: durable metadata for the real running-preview lifecycle. Separate
-- table from build_jobs/project_versions -- a preview is a distinct runtime
-- lifecycle (create -> provision -> start -> health -> expose -> logs ->
-- stop/expire -> cleanup), not a build artifact.

CREATE TABLE IF NOT EXISTS project_previews (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    version_id TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('STARTING', 'RUNNING', 'STOPPED', 'FAILED', 'EXPIRED')),
    preview_url TEXT,
    internal_container_id TEXT,
    error_message TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at TIMESTAMPTZ NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_project_previews_project_created
ON project_previews(project_id, created_at DESC);

-- Used by mark_expired()'s sweep (status='RUNNING' AND expires_at < now()).
CREATE INDEX IF NOT EXISTS idx_project_previews_running_expiry
ON project_previews(expires_at)
WHERE status = 'RUNNING';

-- END SOURCE 014_real_running_preview.sql

-- BEGIN SOURCE 015_preview_lifecycle_and_async_build_parity.sql
-- 015_preview_lifecycle_and_async_build_parity.sql
-- M3 Revision 2 + M1 blocker resolution. Forward-only and idempotent: 014 may
-- already be applied in some environment, so it is extended here rather than
-- edited in place.

-- 1. NOT_PREVIEWABLE is a distinct terminal state (artifact cannot satisfy the
--    preview contract) -- not a runtime FAILED. 014 declared the status CHECK
--    inline on the column, which Postgres names project_previews_status_check.
ALTER TABLE project_previews DROP CONSTRAINT IF EXISTS project_previews_status_check;
ALTER TABLE project_previews ADD CONSTRAINT project_previews_status_check
    CHECK (status IN ('STARTING', 'RUNNING', 'STOPPED', 'FAILED', 'EXPIRED', 'NOT_PREVIEWABLE'));

-- 2. Distributed lifecycle: which host runs the container (stop tasks are
--    routed to that host's queue), the Docker-allocated host port (the
--    external router's upstream), and the bind-mounted source directory the
--    stop task must delete.
ALTER TABLE project_previews
    ADD COLUMN IF NOT EXISTS runtime_host TEXT,
    ADD COLUMN IF NOT EXISTS host_port INTEGER CHECK (host_port IS NULL OR (host_port BETWEEN 1 AND 65535)),
    ADD COLUMN IF NOT EXISTS workdir_path TEXT,
    ADD COLUMN IF NOT EXISTS stopped_at TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS cleaned_at TIMESTAMPTZ;

-- 3. The async build worker runs branding/provenance decoration, which embeds
--    the user-facing project id. build_requests only stored the internal
--    tenant key; nullable so rows written before this migration still load.
ALTER TABLE build_requests
    ADD COLUMN IF NOT EXISTS public_project_id TEXT;

-- 4. Outbox relay: finds rows whose Redis enqueue never happened.
CREATE INDEX IF NOT EXISTS idx_build_outbox_pending
ON build_outbox(created_at)
WHERE enqueued_at IS NULL;

-- END SOURCE 015_preview_lifecycle_and_async_build_parity.sql

-- BEGIN SOURCE 016_durable_modifications.sql
-- 016_durable_modifications.sql
-- M4A/M4B: durable natural-language product modification workflow.
-- Forward-only and idempotent, following 013-015's pattern: new tables plus
-- additive columns, nothing edited in place. Verified against
-- 001_control_plane.sql (project_versions), 011_creator_accounts.sql
-- (creator accounts / project keys) and 013_durable_async_builds.sql
-- (build_outbox / credit_reservations -- reused as-is for modification
-- billing, see the note on reservation_id below) before being written.

-- M4B: one immutable ProductSpec row per ProjectVersion id. version_id is the
-- primary key (not a surrogate id) precisely so there is exactly one spec per
-- version and no way to accidentally load "the latest spec" for a project
-- instead of the exact spec tied to the version being modified -- the
-- invariant M4B's directive names explicitly. No UPDATE path is used against
-- this table anywhere in this codebase (see spec_repository.py): a spec
-- "changing" always means a *new* version getting its own new row.
CREATE TABLE IF NOT EXISTS project_version_specs (
    version_id TEXT PRIMARY KEY REFERENCES project_versions(id),
    project_id TEXT NOT NULL,
    spec_json JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_project_version_specs_project
ON project_version_specs(project_id, created_at DESC);

-- M4A: the durable ModificationRequest.
--
-- promoted_version_id is set only by accept(), and records the *new*
-- project_versions row created when a candidate was promoted to current
-- (see modification_repository.py's accept() -- it commits the candidate's
-- stored repository as a brand-new version, the same append-only way every
-- other write path produces a new version -- nothing is edited in place).
--
-- Deliberately NOT present here: candidate_version_id / candidate_spec_
-- version_id as columns referencing project_versions. An unreviewed
-- candidate is intentionally never committed into project_versions (see
-- modification_candidates below) -- committing it early would make an
-- unreviewed build transiently "current" and would corrupt the very
-- concurrency scenario M4 requires (two candidates built against the same
-- source version N must both still show N as their logical base when
-- reviewed, which only holds if building a candidate never advances
-- `current`). The candidate becomes a real project_versions row for the
-- first time inside accept(), at which point its id is recorded here as
-- promoted_version_id.
CREATE TABLE IF NOT EXISTS modification_requests (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    source_version_id TEXT NOT NULL REFERENCES project_versions(id),
    source_spec_version_id TEXT NOT NULL REFERENCES project_versions(id),
    followup TEXT NOT NULL,
    -- Captured durably at creation time (mirrors build_requests.rights_evidence
    -- -- see job_repository.py / worker_tasks._rights_evidence_from_dicts),
    -- not read from in-memory API-process state when the worker runs: the
    -- worker is a separate process/host and must not depend on the API
    -- process's own memory for a compliance-relevant gate input.
    target_markets_json JSONB NOT NULL DEFAULT '["US", "EU", "IL"]'::jsonb,
    rights_evidence_json JSONB NOT NULL DEFAULT '[]'::jsonb,
    status TEXT NOT NULL CHECK (status IN (
        'QUEUED', 'RUNNING', 'NEEDS_CLARIFICATION', 'READY_FOR_REVIEW',
        'ACCEPTED', 'REJECTED', 'FAILED', 'CONFLICT'
    )),
    classification TEXT CHECK (classification IN ('system_bug', 'missing_requirement', 'change_request', 'ambiguous')),
    classification_reason TEXT,
    billable BOOLEAN,
    promoted_version_id TEXT REFERENCES project_versions(id),
    repair_rounds INTEGER NOT NULL DEFAULT 0,
    evidence_json JSONB NOT NULL DEFAULT '{}'::jsonb,
    error_code TEXT,
    error_message TEXT,
    -- M4G: reuses credit_reservations(build_id) as a generic reservation key
    -- (see subscription_store.py's reserve/settle/release) -- that column is
    -- not foreign-keyed to build_jobs, so a modification_id is a valid key
    -- for it. reservation_id is stored here rather than assumed to equal
    -- `id` so a future reservation scheme change doesn't have to touch this
    -- table's primary key.
    reservation_id TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    accepted_at TIMESTAMPTZ,
    rejected_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_modification_requests_project
ON modification_requests(project_id, created_at DESC);

-- Acceptance test U (concurrency): finding every other still-open
-- modification against the same source version once one of them is accepted.
CREATE INDEX IF NOT EXISTS idx_modification_requests_source_version
ON modification_requests(source_version_id, status);

-- M4C/M4D: the pending candidate produced by a READY_FOR_REVIEW completion --
-- a repository + spec pair that is NOT yet a project_versions row (see the
-- comment on modification_requests above for why). One row per modification,
-- written atomically with the READY_FOR_REVIEW status flip in complete();
-- read back by accept() to promote it, or by a review UI to show it. project_id
-- is denormalized here (rather than requiring a join back to
-- modification_requests) the same way project_version_specs denormalizes it
-- for project_versions in M4B above -- cheap, tenant-scoped reads.
CREATE TABLE IF NOT EXISTS modification_candidates (
    modification_id TEXT PRIMARY KEY REFERENCES modification_requests(id),
    project_id TEXT NOT NULL,
    repository_json JSONB NOT NULL,
    spec_json JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- M4A: transactional outbox for Redis enqueueing, identical shape and
-- purpose to build_outbox (013) -- a separate table because
-- modification_requests.id has no FK relationship to build_requests, and
-- reusing build_outbox would conflate two different queues' pending-dispatch
-- bookkeeping.
CREATE TABLE IF NOT EXISTS modification_outbox (
    id BIGSERIAL PRIMARY KEY,
    modification_id TEXT NOT NULL UNIQUE REFERENCES modification_requests(id),
    enqueued_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_modification_outbox_pending
ON modification_outbox(created_at)
WHERE enqueued_at IS NULL;

-- END SOURCE 016_durable_modifications.sql

-- BEGIN SOURCE 017_capability_foundation.sql
-- 017_capability_foundation.sql
-- Durable M4.95 capability requirements, provider executions and usage evidence.

CREATE TABLE IF NOT EXISTS build_capability_requirements (
    build_id TEXT NOT NULL REFERENCES build_jobs(id) ON DELETE CASCADE,
    requirement_id TEXT NOT NULL,
    capability_key TEXT NOT NULL,
    purpose TEXT NOT NULL,
    required BOOLEAN NOT NULL,
    quantity INTEGER NOT NULL CHECK (quantity >= 1),
    constraints_json JSONB NOT NULL DEFAULT '{}'::jsonb,
    dependency_ids_json JSONB NOT NULL DEFAULT '[]'::jsonb,
    status TEXT NOT NULL DEFAULT 'PLANNED' CHECK (
        status IN ('PLANNED','QUOTED','RESERVED','QUEUED','RUNNING','GENERATED',
                   'VERIFIED','FAILED','CANCELLED','SKIPPED','NOT_CONFIGURED','BLOCKED')
    ),
    selected_provider TEXT,
    pricing_version TEXT,
    estimated_cost_usd NUMERIC(18,8),
    maximum_cost_usd NUMERIC(18,8),
    actual_cost_usd NUMERIC(18,8),
    artifact_key TEXT,
    verification_json JSONB NOT NULL DEFAULT '{}'::jsonb,
    evidence_json JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (estimated_cost_usd IS NULL OR estimated_cost_usd >= 0),
    CHECK (maximum_cost_usd IS NULL OR maximum_cost_usd >= COALESCE(estimated_cost_usd, 0)),
    CHECK (actual_cost_usd IS NULL OR actual_cost_usd >= 0),
    PRIMARY KEY (build_id, requirement_id)
);

CREATE INDEX IF NOT EXISTS idx_build_capability_requirements_status
    ON build_capability_requirements(build_id, status);
CREATE INDEX IF NOT EXISTS idx_build_capability_requirements_key
    ON build_capability_requirements(capability_key, created_at DESC);

-- Execution state and lease ownership are deliberately separate. The row is
-- durably created in SUBMITTING before any external paid submit; lease fields
-- are nullable until a worker claims it. A restarted worker reuses the same
-- idempotency_key/provider_task_id instead of creating a second paid job.
CREATE TABLE IF NOT EXISTS provider_execution_attempts (
    id TEXT PRIMARY KEY,
    build_id TEXT NOT NULL,
    requirement_id TEXT NOT NULL,
    provider TEXT NOT NULL,
    pricing_version TEXT NOT NULL,
    idempotency_key TEXT NOT NULL UNIQUE,
    provider_task_id TEXT,
    status TEXT NOT NULL DEFAULT 'SUBMITTING' CHECK (
        status IN ('SUBMITTING','SUBMITTED','RUNNING','SUCCEEDED','FAILED','CANCELLED')
    ),
    lease_owner TEXT,
    lease_expires_at TIMESTAMPTZ,
    last_error_code TEXT,
    last_error_message TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (build_id, requirement_id)
        REFERENCES build_capability_requirements(build_id, requirement_id)
        ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_provider_execution_external_task
    ON provider_execution_attempts(provider, provider_task_id)
    WHERE provider_task_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_provider_execution_resume
    ON provider_execution_attempts(status, lease_expires_at);

CREATE TABLE IF NOT EXISTS provider_usage_events (
    id BIGSERIAL PRIMARY KEY,
    event_key TEXT NOT NULL UNIQUE,
    build_id TEXT NOT NULL,
    requirement_id TEXT NOT NULL,
    provider TEXT NOT NULL,
    pricing_version TEXT NOT NULL,
    estimated_cost_usd NUMERIC(18,8) NOT NULL CHECK (estimated_cost_usd >= 0),
    maximum_cost_usd NUMERIC(18,8) NOT NULL CHECK (maximum_cost_usd >= estimated_cost_usd),
    actual_cost_usd NUMERIC(18,8),
    usage_json JSONB NOT NULL DEFAULT '{}'::jsonb,
    evidence_json JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (actual_cost_usd IS NULL OR actual_cost_usd >= 0),
    FOREIGN KEY (build_id, requirement_id)
        REFERENCES build_capability_requirements(build_id, requirement_id)
        ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_provider_usage_build
    ON provider_usage_events(build_id, requirement_id, provider);

-- END SOURCE 017_capability_foundation.sql

-- BEGIN SOURCE 018_identity_lifecycle.sql
-- 018_identity_lifecycle.sql
-- M5 Task 2: durable creator identity/session lifecycle. Raw session, email
-- verification and password-reset tokens are never persisted.

ALTER TABLE creator_accounts
    ADD COLUMN IF NOT EXISTS account_status TEXT NOT NULL DEFAULT 'ACTIVE';
ALTER TABLE creator_accounts
    ADD COLUMN IF NOT EXISTS email_verified_at TIMESTAMPTZ;

CREATE TABLE IF NOT EXISTS creator_sessions (
    session_id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES creator_accounts(id) ON DELETE CASCADE,
    token_hash TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    revoked_at TIMESTAMPTZ,
    last_seen_at TIMESTAMPTZ,
    CHECK (expires_at > created_at)
);
CREATE INDEX IF NOT EXISTS idx_creator_sessions_user_active
    ON creator_sessions(user_id, created_at DESC)
    WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS creator_identity_tokens (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES creator_accounts(id) ON DELETE CASCADE,
    purpose TEXT NOT NULL CHECK (purpose IN ('EMAIL_VERIFY','PASSWORD_RESET')),
    token_hash TEXT NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    consumed_at TIMESTAMPTZ,
    CHECK (expires_at > created_at)
);
CREATE INDEX IF NOT EXISTS idx_creator_identity_tokens_lookup
    ON creator_identity_tokens(token_hash, purpose)
    WHERE consumed_at IS NULL;

CREATE TABLE IF NOT EXISTS creator_consents (
    user_id TEXT NOT NULL REFERENCES creator_accounts(id) ON DELETE CASCADE,
    consent_type TEXT NOT NULL,
    version TEXT NOT NULL,
    source TEXT NOT NULL,
    accepted_at TIMESTAMPTZ NOT NULL,
    PRIMARY KEY(user_id, consent_type, version)
);

CREATE TABLE IF NOT EXISTS creator_privacy_requests (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES creator_accounts(id) ON DELETE CASCADE,
    request_type TEXT NOT NULL CHECK (request_type IN ('DATA_EXPORT','ACCOUNT_DELETION')),
    status TEXT NOT NULL CHECK (status IN ('REQUESTED','PROCESSING','COMPLETED','REJECTED')),
    requested_at TIMESTAMPTZ NOT NULL,
    completed_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_creator_privacy_requests_user
    ON creator_privacy_requests(user_id, requested_at DESC);

-- END SOURCE 018_identity_lifecycle.sql

-- BEGIN SOURCE 019_project_lifecycle.sql
-- 019_project_lifecycle.sql
-- M5 Task 3: archive/delete are metadata state transitions. Project rows and
-- downstream versions/build/evidence are deliberately not hard-deleted here.

ALTER TABLE creator_projects ADD COLUMN IF NOT EXISTS archived_at TIMESTAMPTZ;
ALTER TABLE creator_projects ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;
ALTER TABLE creator_projects ADD COLUMN IF NOT EXISTS retention_until TIMESTAMPTZ;
ALTER TABLE creator_projects ADD COLUMN IF NOT EXISTS tombstone_reason TEXT;

CREATE INDEX IF NOT EXISTS idx_creator_projects_owner_active
    ON creator_projects(owner_id, updated_at DESC)
    WHERE deleted_at IS NULL AND archived_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_creator_projects_owner_archived
    ON creator_projects(owner_id, updated_at DESC)
    WHERE deleted_at IS NULL AND archived_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_creator_projects_retention
    ON creator_projects(retention_until)
    WHERE deleted_at IS NOT NULL;

-- END SOURCE 019_project_lifecycle.sql

-- BEGIN SOURCE 020_m5_build_contracts.sql
-- M5 Task 4: immutable, versioned Build Contracts.
-- A build contract binds one product-intent revision to deterministic capability,
-- infrastructure, security, acceptance and cost-envelope truth.

CREATE TABLE IF NOT EXISTS m5_build_contracts (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES creator_projects(id) ON DELETE RESTRICT,
    contract_version INTEGER NOT NULL CHECK (contract_version > 0),
    status TEXT NOT NULL CHECK (status IN ('READY','NEEDS_CLARIFICATION','BLOCKED')),
    capability_plan_fingerprint TEXT NOT NULL,
    contract_fingerprint TEXT NOT NULL,
    contract_json JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    UNIQUE(project_id, contract_version)
);

CREATE INDEX IF NOT EXISTS idx_m5_build_contracts_project_version
    ON m5_build_contracts(project_id, contract_version DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_m5_build_contracts_project_fingerprint
    ON m5_build_contracts(project_id, contract_fingerprint);

CREATE OR REPLACE FUNCTION reject_m5_build_contract_mutation()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION 'm5 build contracts are immutable; create a new contract revision';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_m5_build_contracts_immutable ON m5_build_contracts;
CREATE TRIGGER trg_m5_build_contracts_immutable
BEFORE UPDATE OR DELETE ON m5_build_contracts
FOR EACH ROW EXECUTE FUNCTION reject_m5_build_contract_mutation();

-- M5 Task 5: every new durable build request is bound to one immutable
-- Build Contract revision. Nullable preserves readability of pre-M5 rows.
ALTER TABLE build_requests
    ADD COLUMN IF NOT EXISTS build_contract_id TEXT REFERENCES m5_build_contracts(id) ON DELETE RESTRICT;

CREATE INDEX IF NOT EXISTS idx_build_requests_build_contract
    ON build_requests(build_contract_id)
    WHERE build_contract_id IS NOT NULL;

CREATE OR REPLACE FUNCTION m5_build_request_contract_project()
RETURNS TRIGGER AS $$
DECLARE
    contract_project TEXT;
BEGIN
    IF NEW.build_contract_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF NEW.public_project_id IS NULL THEN
        RAISE EXCEPTION 'bound build request requires public_project_id';
    END IF;
    SELECT project_id INTO contract_project
      FROM m5_build_contracts
     WHERE id = NEW.build_contract_id;
    IF contract_project IS NULL THEN
        RAISE EXCEPTION 'build contract does not exist';
    END IF;
    IF contract_project IS DISTINCT FROM NEW.public_project_id THEN
        RAISE EXCEPTION 'build contract project mismatch';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_m5_build_request_contract_project ON build_requests;
CREATE TRIGGER trg_m5_build_request_contract_project
BEFORE INSERT OR UPDATE OF build_contract_id, public_project_id ON build_requests
FOR EACH ROW EXECUTE FUNCTION m5_build_request_contract_project();

-- END SOURCE 020_m5_build_contracts.sql

-- BEGIN SOURCE 021_generated_app_bindings.sql
-- M5 Task 7: durable generated-app infrastructure bindings.
-- One row per (profile, project, environment, kind). Rows hold secret
-- REFERENCES (env:/vault:) only; the database rejects anything else.
-- Ownership (tenant/project/environment/kind/profile) is immutable once written.

CREATE TABLE IF NOT EXISTS generated_app_bindings (
    binding_id TEXT PRIMARY KEY,
    idempotency_key TEXT NOT NULL,
    profile_key TEXT NOT NULL,
    tenant_id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    environment TEXT NOT NULL CHECK (environment IN ('preview','production')),
    kind TEXT NOT NULL CHECK (kind IN ('database','auth_session','object_storage','scheduled_http','outbound')),
    status TEXT NOT NULL CHECK (status IN ('LIVE','NOT_CONFIGURED','BLOCKED','REVOKED')),
    resource_name TEXT NOT NULL,
    provisioner TEXT NOT NULL,
    secret_references JSONB NOT NULL DEFAULT '{}'::jsonb,
    public_config JSONB NOT NULL DEFAULT '{}'::jsonb,
    evidence JSONB NOT NULL DEFAULT '{}'::jsonb,
    status_reason TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    revoked_at TIMESTAMPTZ,
    CONSTRAINT generated_app_bindings_idempotency UNIQUE (idempotency_key),
    CONSTRAINT generated_app_bindings_scope UNIQUE (profile_key, project_id, environment, kind),
    CONSTRAINT generated_app_bindings_refs_object CHECK (jsonb_typeof(secret_references) = 'object'),
    -- every secret_references value must be an env: or vault: reference, never a value
    CONSTRAINT generated_app_bindings_refs_only CHECK (
        NOT jsonb_path_exists(secret_references, '$.* ? (!(@ like_regex "^(env|vault):[A-Za-z0-9_./-]+$"))')
    ),
    CONSTRAINT generated_app_bindings_revoked_at CHECK ((status = 'REVOKED') = (revoked_at IS NOT NULL))
);

CREATE INDEX IF NOT EXISTS idx_generated_app_bindings_project_env
    ON generated_app_bindings(project_id, environment);

CREATE OR REPLACE FUNCTION reject_generated_app_binding_ownership_change()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.project_id IS DISTINCT FROM OLD.project_id
       OR NEW.environment IS DISTINCT FROM OLD.environment
       OR NEW.kind IS DISTINCT FROM OLD.kind
       OR NEW.profile_key IS DISTINCT FROM OLD.profile_key
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key THEN
        RAISE EXCEPTION 'cannot change binding ownership of generated app binding %', OLD.binding_id;
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_generated_app_bindings_ownership ON generated_app_bindings;
CREATE TRIGGER trg_generated_app_bindings_ownership
BEFORE UPDATE ON generated_app_bindings
FOR EACH ROW EXECUTE FUNCTION reject_generated_app_binding_ownership_change();

-- END SOURCE 021_generated_app_bindings.sql

-- BEGIN SOURCE 026_media_provider_submissions.sql
-- M5 Task 9 (migration 026; 022-025 are reserved by the M5 plan for Tasks 12-15): durable submission journal for paid external media providers.
-- An INTENT row is written before a paid submit; the provider task id is
-- recorded right after. A crash between the two leaves an INTENT row, which
-- makes the adapter fail closed (or rely on provider-side idempotency) instead
-- of blindly paying for a duplicate job.

CREATE TABLE IF NOT EXISTS media_provider_submissions (
    idempotency_key TEXT PRIMARY KEY,
    provider TEXT NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('INTENT','SUBMITTED')),
    provider_task_id TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT media_provider_submissions_task CHECK ((state = 'SUBMITTED') = (provider_task_id IS NOT NULL))
);

CREATE INDEX IF NOT EXISTS idx_media_provider_submissions_intent
    ON media_provider_submissions(provider, created_at)
    WHERE state = 'INTENT';

-- END SOURCE 026_media_provider_submissions.sql

-- BEGIN SOURCE 027_task_attempts.sql
-- Attempt Ledger (migration 027): one immutable row per provider call or
-- verification run inside a build. Source of truth for execution evidence and
-- measured cost (Operating Contract 29A). Rows are append-only; the only
-- later write is final_outcome when the build reaches a terminal state.
--
-- Cost truth (three layers, never merged):
--   authorized_cost_usd     maximum authorized before the call (budget gate)
--   expected_cost_usd       estimator output; NULL until an estimator exists
--   metered_cost_usd        usage measured by us x versioned catalog price
--   provider_reported_cost_usd  the provider's own figure, if it sent one
--   reconciled_cost_usd     matched to the provider invoice (later process)
-- NULL means "not known", never zero.

CREATE TABLE IF NOT EXISTS task_attempts (
    attempt_id                  TEXT PRIMARY KEY,
    build_id                    TEXT NOT NULL,
    tenant_id                   TEXT,
    project_id                  TEXT,
    task_id                     TEXT NOT NULL,
    task_type                   TEXT NOT NULL,
    attempt_seq                 INTEGER NOT NULL CHECK (attempt_seq >= 0),
    kind                        TEXT NOT NULL CHECK (kind IN ('provider_call', 'verification')),
    provider                    TEXT,
    model                       TEXT,
    model_version               TEXT,
    provider_request_id         TEXT,
    trace_id                    TEXT,
    policy_version              TEXT,
    routing_policy_version      TEXT,
    prompt_version              TEXT,
    price_catalog_version       TEXT,
    selection_reason            TEXT,
    selected_candidate          TEXT,
    candidate_set               JSONB,
    fallback_rank               INTEGER CHECK (fallback_rank IS NULL OR fallback_rank >= 0),
    reservation_id              TEXT,
    authorized_cost_usd         NUMERIC(14, 8) CHECK (authorized_cost_usd IS NULL OR authorized_cost_usd >= 0),
    expected_cost_usd           NUMERIC(14, 8) CHECK (expected_cost_usd IS NULL OR expected_cost_usd >= 0),
    metered_cost_usd            NUMERIC(14, 8) CHECK (metered_cost_usd IS NULL OR metered_cost_usd >= 0),
    provider_reported_cost_usd  NUMERIC(14, 8) CHECK (provider_reported_cost_usd IS NULL OR provider_reported_cost_usd >= 0),
    reconciled_cost_usd         NUMERIC(14, 8) CHECK (reconciled_cost_usd IS NULL OR reconciled_cost_usd >= 0),
    input_tokens                INTEGER CHECK (input_tokens IS NULL OR input_tokens >= 0),
    output_tokens               INTEGER CHECK (output_tokens IS NULL OR output_tokens >= 0),
    cached_tokens               INTEGER CHECK (cached_tokens IS NULL OR cached_tokens >= 0),
    latency_ms                  INTEGER CHECK (latency_ms IS NULL OR latency_ms >= 0),
    outcome                     TEXT NOT NULL CHECK (outcome IN ('ok', 'error', 'unknown')),
    verification_class          TEXT CHECK (verification_class IS NULL OR verification_class IN
                                    ('PASS', 'REPAIRABLE_FAIL', 'RETRYABLE_FAIL', 'ESCALATABLE_FAIL', 'FATAL_FAIL')),
    failure_reason              TEXT,
    final_outcome               TEXT,
    -- Data governance (Operating Contract 29J)
    data_sensitivity            TEXT NOT NULL DEFAULT 'tenant_private',
    training_eligible           BOOLEAN NOT NULL DEFAULT FALSE,
    created_at                  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_task_attempts_build ON task_attempts(build_id, attempt_seq);
CREATE INDEX IF NOT EXISTS idx_task_attempts_model_task ON task_attempts(model, task_type, created_at);
CREATE INDEX IF NOT EXISTS idx_task_attempts_tenant ON task_attempts(tenant_id, created_at);

-- END SOURCE 027_task_attempts.sql

-- BEGIN SOURCE 028_task_attempt_counters.sql
-- Attempt Ledger counters (migration 028; founder decision 2026-10-07, section 9).
-- Per-attempt snapshot of the build's counters at the moment the attempt was
-- recorded, so every row is self-describing without re-aggregating the build:
--   retry_count       prior attempts of the same logical call (0 = first try)
--   repair_count      repair calls made in this build so far (incl. this one)
--   regenerate_count  code generations beyond the first in this build so far
--   escalation_count  escalated attempts in this build so far
--   fallback_count    attempts served by a non-first candidate so far
-- NULL means "not recorded" (rows written before this migration).

ALTER TABLE task_attempts
    ADD COLUMN IF NOT EXISTS retry_count      INTEGER CHECK (retry_count IS NULL OR retry_count >= 0),
    ADD COLUMN IF NOT EXISTS repair_count     INTEGER CHECK (repair_count IS NULL OR repair_count >= 0),
    ADD COLUMN IF NOT EXISTS regenerate_count INTEGER CHECK (regenerate_count IS NULL OR regenerate_count >= 0),
    ADD COLUMN IF NOT EXISTS escalation_count INTEGER CHECK (escalation_count IS NULL OR escalation_count >= 0),
    ADD COLUMN IF NOT EXISTS fallback_count   INTEGER CHECK (fallback_count IS NULL OR fallback_count >= 0);

-- END SOURCE 028_task_attempt_counters.sql

-- BEGIN SOURCE 029_internal_entitlements.sql
-- Internal entitlements and reservation funding source (migration 029).
-- Founder decision 2026-10-07 (#24): internal QA funding is an explicit,
-- audited entitlement bound to an account id and an environment scope, never
-- an implicit email match, and its budget is separate from the customer plan.
--
-- Only INTERNAL_QA in the staging scope exists. Adding another entitlement or
-- scope (for example production) is a deliberate schema change, not a row.
-- Revocation keeps the row (audit trail); at most one active grant per
-- (account, entitlement, environment).

CREATE TABLE IF NOT EXISTS internal_entitlements (
    id              TEXT PRIMARY KEY,
    account_id      TEXT NOT NULL REFERENCES creator_accounts(id),
    entitlement     TEXT NOT NULL CHECK (entitlement IN ('INTERNAL_QA')),
    environment     TEXT NOT NULL CHECK (environment IN ('staging')),
    reason          TEXT NOT NULL CHECK (length(trim(reason)) > 0),
    granted_by      TEXT NOT NULL CHECK (length(trim(granted_by)) > 0),
    granted_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    revoked_at      TIMESTAMPTZ,
    revoked_by      TEXT,
    revoke_reason   TEXT,
    CONSTRAINT internal_entitlements_revocation CHECK ((revoked_at IS NULL) = (revoked_by IS NULL))
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_internal_entitlements_active
    ON internal_entitlements(account_id, entitlement, environment)
    WHERE revoked_at IS NULL;

-- Which budget funded a reservation. Customer-plan reservations move the
-- account's plan counters; internal QA reservations never do, and only they
-- count against the internal QA caps.
ALTER TABLE credit_reservations
    ADD COLUMN IF NOT EXISTS funding_source TEXT NOT NULL DEFAULT 'customer_plan'
        CHECK (funding_source IN ('customer_plan', 'internal_qa'));

CREATE INDEX IF NOT EXISTS idx_credit_reservations_internal_qa
    ON credit_reservations(created_at)
    WHERE funding_source = 'internal_qa';

-- END SOURCE 029_internal_entitlements.sql

-- BEGIN SOURCE 030_project_briefs_and_approvals.sql
-- Discovery brief and server-bound build approval (migration 030).
-- Master directive 2026-10-09 §4-5.
--
-- project_briefs: every change to the discovery answers is a new immutable
-- revision. Writers use compare-and-set on the revision number (the UNIQUE
-- constraint makes a lost race fail instead of overwriting).
--
-- build_approvals: "approve and start building" binds the user, project,
-- brief revision + fingerprint, build contract + fingerprint and the budget
-- quote (budget revision) for a limited time. A build consumes exactly one
-- ACTIVE approval; a newer brief revision or a different quote makes it stale.

CREATE TABLE IF NOT EXISTS project_briefs (
    id           TEXT PRIMARY KEY,
    project_id   TEXT NOT NULL REFERENCES creator_projects(id) ON DELETE CASCADE,
    revision     INTEGER NOT NULL CHECK (revision > 0),
    account_id   TEXT NOT NULL REFERENCES creator_accounts(id),
    mode         TEXT NOT NULL CHECK (mode IN ('guided', 'recommend')),
    complete     BOOLEAN NOT NULL,
    brief_json   JSONB NOT NULL,
    fingerprint  TEXT NOT NULL,
    request_key  TEXT,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (project_id, revision)
);
-- A retried submission (same idempotency key) returns the revision it made.
CREATE UNIQUE INDEX IF NOT EXISTS uq_project_briefs_request_key
    ON project_briefs(project_id, request_key) WHERE request_key IS NOT NULL;

CREATE OR REPLACE FUNCTION reject_project_brief_mutation()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION 'project briefs are immutable; write a new revision';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_project_briefs_immutable ON project_briefs;
CREATE TRIGGER trg_project_briefs_immutable
BEFORE UPDATE ON project_briefs
FOR EACH ROW EXECUTE FUNCTION reject_project_brief_mutation();

CREATE TABLE IF NOT EXISTS build_approvals (
    id                    TEXT PRIMARY KEY,
    project_id            TEXT NOT NULL REFERENCES creator_projects(id) ON DELETE CASCADE,
    account_id            TEXT NOT NULL REFERENCES creator_accounts(id),
    brief_id              TEXT NOT NULL REFERENCES project_briefs(id),
    brief_revision        INTEGER NOT NULL,
    brief_fingerprint     TEXT NOT NULL,
    build_contract_id     TEXT NOT NULL REFERENCES m5_build_contracts(id),
    contract_fingerprint  TEXT NOT NULL,
    budget_fingerprint    TEXT NOT NULL,
    status                TEXT NOT NULL CHECK (status IN ('ACTIVE', 'USED', 'INVALIDATED', 'EXPIRED')),
    expires_at            TIMESTAMPTZ NOT NULL,
    used_by_build_id      TEXT,
    invalidated_reason    TEXT,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT build_approvals_used CHECK ((status = 'USED') = (used_by_build_id IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS idx_build_approvals_project ON build_approvals(project_id, created_at DESC);

-- END SOURCE 030_project_briefs_and_approvals.sql

-- BEGIN SOURCE 031_build_cancel_and_events.sql
-- Stop a build and show what it is doing; preview data durability (migration 031).
-- Master directive 2026-10-09 §10 (task states, cancel) and §12 (the user
-- always sees what is happening).
--
-- cancel_requested_at: set by the owner's "stop" on a RUNNING build. The
-- worker checks it before every model call and every sandbox run, stops
-- there, settles only what was really used and writes CANCELLED. A QUEUED
-- build is cancelled directly by the API (the worker's QUEUED -> RUNNING
-- claim then fails, so it never starts).
--
-- build_events: an append-only, human-readable log of the build's steps
-- (phase changes, model calls by task, test runs and their result). It is
-- what the workspace shows as the live log. Messages never contain secrets
-- or generated code; they are short sentences written by the worker.

ALTER TABLE build_jobs ADD COLUMN IF NOT EXISTS cancel_requested_at TIMESTAMPTZ;
ALTER TABLE build_jobs ADD COLUMN IF NOT EXISTS cancel_requested_by TEXT;

CREATE TABLE IF NOT EXISTS build_events (
    seq        BIGSERIAL PRIMARY KEY,
    build_id   TEXT NOT NULL REFERENCES build_jobs(id) ON DELETE CASCADE,
    at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    kind       TEXT NOT NULL CHECK (kind IN ('phase', 'model', 'check', 'repair', 'cancel', 'info')),
    message    TEXT NOT NULL CHECK (length(message) <= 600)
);

CREATE INDEX IF NOT EXISTS idx_build_events_build_seq ON build_events (build_id, seq);

-- Directive §13: whether a preview's product data survives a restart and a
-- new version ('persistent', one directory per project on the preview host)
-- or lives only in the container's tmpfs ('temporary'). NULL = before 031.
ALTER TABLE project_previews ADD COLUMN IF NOT EXISTS data_storage TEXT
    CHECK (data_storage IS NULL OR data_storage IN ('persistent', 'temporary'));

-- END SOURCE 031_build_cancel_and_events.sql

-- BEGIN SOURCE 032_preview_access.sql
-- Private previews (migration 032). Autonomous completion directive §4.
--
-- Real-server finding 2026-10-09: preview hostnames are published in
-- certificate-transparency logs (on-demand TLS), and internet scanners hit
-- them within minutes. An unguessable URL is not access control.
--
-- access_mode: PRIVATE (default; only holders of an owner token), SHARED
-- (owner tokens + share tokens the owner created), PUBLIC (anyone). Existing
-- rows become PRIVATE.
--
-- preview_access_tokens: random tokens, stored only as SHA-256; issued by the
-- API to the authenticated owner (short-lived) or as a share link; checked by
-- the preview router on the host; revocable; usage counted for audit.
-- preview_access_audit: issued / revoked / mode changes and refused requests
-- (aggregated per preview and minute), never the token itself.

ALTER TABLE project_previews ADD COLUMN IF NOT EXISTS access_mode TEXT NOT NULL DEFAULT 'PRIVATE'
    CHECK (access_mode IN ('PRIVATE', 'SHARED', 'PUBLIC'));

CREATE TABLE IF NOT EXISTS preview_access_tokens (
    token_hash   TEXT PRIMARY KEY,
    preview_id   TEXT NOT NULL REFERENCES project_previews(id) ON DELETE CASCADE,
    kind         TEXT NOT NULL CHECK (kind IN ('owner', 'share')),
    issued_to    TEXT,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at   TIMESTAMPTZ NOT NULL,
    revoked_at   TIMESTAMPTZ,
    last_used_at TIMESTAMPTZ,
    uses         INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_preview_access_tokens_preview ON preview_access_tokens (preview_id);

CREATE TABLE IF NOT EXISTS preview_access_audit (
    id         BIGSERIAL PRIMARY KEY,
    preview_id TEXT NOT NULL,
    at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    event      TEXT NOT NULL CHECK (event IN ('issued', 'revoked', 'mode', 'denied')),
    detail     TEXT NOT NULL DEFAULT '' CHECK (length(detail) <= 300)
);

CREATE INDEX IF NOT EXISTS idx_preview_access_audit_preview ON preview_access_audit (preview_id, at);

-- END SOURCE 032_preview_access.sql

-- BEGIN SOURCE 033_recovery_and_change_parity.sql
-- Crash recovery and change (modification) parity (migration 033).
-- Autonomous completion directive §5.
--
-- heartbeat_at: written by the worker at every step boundary (before each
-- model call and each sandbox run). A RUNNING job whose heartbeat is older
-- than the recovery limit lost its worker (crash, OOM, host restart); the
-- janitor puts it back in the queue once (recovery_attempts) and fails it
-- after that, releasing its reservation. A stop request on such a job ends
-- it CANCELLED instead.
--
-- Changes get the same stop flag, heartbeat and live log as builds:
-- build_events now carries both kinds (job_kind); the foreign key to
-- build_jobs is dropped so a change's id can be logged (ownership is checked
-- by the API through the owning table).

ALTER TABLE build_jobs ADD COLUMN IF NOT EXISTS heartbeat_at TIMESTAMPTZ;
ALTER TABLE build_jobs ADD COLUMN IF NOT EXISTS recovery_attempts INTEGER NOT NULL DEFAULT 0;

ALTER TABLE modification_requests ADD COLUMN IF NOT EXISTS cancel_requested_at TIMESTAMPTZ;
ALTER TABLE modification_requests ADD COLUMN IF NOT EXISTS heartbeat_at TIMESTAMPTZ;
ALTER TABLE modification_requests ADD COLUMN IF NOT EXISTS recovery_attempts INTEGER NOT NULL DEFAULT 0;
ALTER TABLE modification_requests DROP CONSTRAINT IF EXISTS modification_requests_status_check;
ALTER TABLE modification_requests ADD CONSTRAINT modification_requests_status_check CHECK (status IN (
    'QUEUED', 'RUNNING', 'NEEDS_CLARIFICATION', 'READY_FOR_REVIEW',
    'ACCEPTED', 'REJECTED', 'FAILED', 'CONFLICT', 'CANCELLED'
));

ALTER TABLE build_events DROP CONSTRAINT IF EXISTS build_events_build_id_fkey;
ALTER TABLE build_events ADD COLUMN IF NOT EXISTS job_kind TEXT NOT NULL DEFAULT 'build'
    CHECK (job_kind IN ('build', 'modification'));

-- END SOURCE 033_recovery_and_change_parity.sql

-- BEGIN SOURCE 034_agent_runtime.sql
-- Durable agent execution (migration 034). Autonomous completion directive §12.
--
-- agent_runs: one task graph per build or change.
-- agent_tasks: one row per agent task; state machine enforced by the runtime
--   (PENDING, READY, RUNNING, WAITING, BLOCKED, VERIFYING, REPAIRING,
--    SUCCEEDED, FAILED, CANCEL_REQUESTED, CANCELLED); survives restarts.
--   verified_by_task points at the independent verifier's task.
-- agent_handoffs: structured handoffs between agents (payload refs only).
-- agent_memory: per-project, per-agent facts (no secrets).
-- platform_check_results: results of real-server golden/post-deploy checks,
--   the evidence the capability auditor and the quality gate read.

CREATE TABLE IF NOT EXISTS agent_runs (
    id           TEXT PRIMARY KEY,
    subject_kind TEXT NOT NULL CHECK (subject_kind IN ('build', 'modification', 'check')),
    subject_id   TEXT NOT NULL,
    budget_usd   NUMERIC(12, 6),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    finished_at  TIMESTAMPTZ,
    outcome      TEXT
);
CREATE INDEX IF NOT EXISTS idx_agent_runs_subject ON agent_runs (subject_kind, subject_id);

CREATE TABLE IF NOT EXISTS agent_tasks (
    id               TEXT PRIMARY KEY,
    run_id           TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,
    agent_key        TEXT NOT NULL,
    skill_keys       JSONB NOT NULL DEFAULT '[]'::jsonb,
    state            TEXT NOT NULL CHECK (state IN ('PENDING', 'READY', 'RUNNING', 'WAITING', 'BLOCKED', 'VERIFYING',
                                                     'REPAIRING', 'SUCCEEDED', 'FAILED', 'CANCEL_REQUESTED', 'CANCELLED')),
    depends_on       JSONB NOT NULL DEFAULT '[]'::jsonb,
    attempt          INTEGER NOT NULL DEFAULT 1,
    budget_usd       NUMERIC(12, 6),
    cost_usd         NUMERIC(12, 6) NOT NULL DEFAULT 0,
    verified_by_task TEXT,
    evidence         JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    started_at       TIMESTAMPTZ,
    finished_at      TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_agent_tasks_run ON agent_tasks (run_id);
CREATE INDEX IF NOT EXISTS idx_agent_tasks_agent ON agent_tasks (agent_key, finished_at);

CREATE TABLE IF NOT EXISTS agent_handoffs (
    id         BIGSERIAL PRIMARY KEY,
    run_id     TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,
    from_task  TEXT NOT NULL,
    to_agent   TEXT NOT NULL,
    payload    JSONB NOT NULL DEFAULT '{}'::jsonb,
    at         TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS agent_memory (
    project_id TEXT NOT NULL,
    agent_key  TEXT NOT NULL,
    key        TEXT NOT NULL,
    value      JSONB NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (project_id, agent_key, key)
);

CREATE TABLE IF NOT EXISTS platform_check_results (
    id         BIGSERIAL PRIMARY KEY,
    check_key  TEXT NOT NULL,
    stage      TEXT NOT NULL,
    passed     BOOLEAN NOT NULL,
    detail     TEXT NOT NULL DEFAULT '' CHECK (length(detail) <= 2000),
    commit_sha TEXT,
    at         TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_platform_check_results_key ON platform_check_results (check_key, at DESC);

-- END SOURCE 034_agent_runtime.sql

-- BEGIN SOURCE 035_build_stage_results.sql
-- Durable per-stage quality evidence (migration 035). Issue #6 P1, Production
-- Assurance v2 §5. Additive; rollback = DROP TABLE build_stage_results (nothing
-- else reads it).
--
-- One row per check of the release policy for one build: the checked artifact
-- digest, the policy version, who verified (platform module or model) and
-- whether that verifier is independent of the generating model. Rows are
-- immutable; a repeated write for the same (build, artifact, policy, check) is
-- a no-op, so a duplicate delivery or a recovered worker cannot change them.
-- A different artifact digest is a different row: evidence never transfers
-- from one repository state to another.

CREATE TABLE IF NOT EXISTS build_stage_results (
    id              BIGSERIAL PRIMARY KEY,
    build_id        TEXT NOT NULL,
    job_kind        TEXT NOT NULL DEFAULT 'build' CHECK (job_kind IN ('build', 'modification', 'replay')),
    tenant_key      TEXT,
    stage           TEXT NOT NULL,
    check_key       TEXT NOT NULL,
    status          TEXT NOT NULL CHECK (status IN ('PASS', 'FAIL', 'NOT_RUN', 'UNKNOWN', 'NOT_APPLICABLE')),
    required        BOOLEAN NOT NULL,
    verifier        TEXT NOT NULL,
    independent     BOOLEAN NOT NULL,
    severity        TEXT NOT NULL,
    detail          TEXT NOT NULL DEFAULT '' CHECK (length(detail) <= 1000),
    artifact_sha256 TEXT NOT NULL,
    policy_version  TEXT NOT NULL,
    report_schema   TEXT NOT NULL,
    decision        TEXT NOT NULL CHECK (decision IN ('READY', 'FAILED')),
    source_commit   TEXT,
    environment     TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (build_id, artifact_sha256, policy_version, check_key)
);
CREATE INDEX IF NOT EXISTS idx_build_stage_results_build ON build_stage_results (build_id);
CREATE INDEX IF NOT EXISTS idx_build_stage_results_check ON build_stage_results (check_key, status, created_at DESC);

-- END SOURCE 035_build_stage_results.sql

-- BEGIN SOURCE 036_intelligence_plane.sql
-- Wave A intelligence control plane (migration 036). Additive only; rollback =
-- DROP TABLE provider_health, intake_messages, execution_plans (no other table
-- references them).
--
-- provider_health: durable circuit breaker per model route (route name only;
--   never keys or request content). Read by every gateway before routing.
-- intake_messages: the customer's free-text intake conversation per project,
--   bound to the brief revision it produced. The brief (project_briefs) stays
--   the source of truth; these rows are the audit trail of how it changed.
-- execution_plans: the Chief Architect's validated plan + task DAG for one
--   brief revision (immutable; identified by its content fingerprint).

CREATE TABLE IF NOT EXISTS provider_health (
    route       TEXT PRIMARY KEY,
    state       TEXT NOT NULL CHECK (state IN ('HEALTHY', 'DEGRADED', 'RATE_LIMITED', 'CREDIT_EXHAUSTED', 'AUTH_INVALID',
                                               'UNAVAILABLE', 'RETIRED', 'UNKNOWN')),
    detail      TEXT NOT NULL DEFAULT '' CHECK (length(detail) <= 300),
    since       TIMESTAMPTZ,
    open_until  TIMESTAMPTZ,
    recheck_at  TIMESTAMPTZ,
    failures    INTEGER NOT NULL DEFAULT 0,
    reset_by    TEXT NOT NULL DEFAULT '',
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS intake_messages (
    id              BIGSERIAL PRIMARY KEY,
    project_id      TEXT NOT NULL,
    account_id      TEXT NOT NULL,
    role            TEXT NOT NULL CHECK (role IN ('customer', 'assistant')),
    content         TEXT NOT NULL CHECK (length(content) <= 8000),
    brief_revision  INTEGER,
    interpretation  JSONB NOT NULL DEFAULT '{}'::jsonb,
    interpreter     TEXT NOT NULL DEFAULT 'deterministic',
    cost_usd        NUMERIC(12, 6) NOT NULL DEFAULT 0,
    request_key     TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_intake_messages_project ON intake_messages (project_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_intake_messages_request
    ON intake_messages (project_id, request_key, role) WHERE request_key IS NOT NULL;

CREATE TABLE IF NOT EXISTS execution_plans (
    id                TEXT PRIMARY KEY,
    project_id        TEXT NOT NULL,
    brief_revision    INTEGER NOT NULL,
    brief_fingerprint TEXT NOT NULL,
    plan_schema       TEXT NOT NULL,
    fingerprint       TEXT NOT NULL,
    plan              JSONB NOT NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (project_id, fingerprint)
);
CREATE INDEX IF NOT EXISTS idx_execution_plans_project ON execution_plans (project_id, brief_revision);

-- END SOURCE 036_intelligence_plane.sql

-- BEGIN SOURCE 037_intake_budget_reservations.sql
-- Intake model budget reservations (Issue #12). Additive only.
--
-- Lifecycle of one paid intake model invocation:
--   QUOTE (code) -> RESERVE -> CLAIM -> EXECUTE -> METER/SETTLE -> RECONCILE
-- * RESERVE inserts the reservation, its budget scopes and the outbox row in
--   ONE transaction, after locking the scope anchor rows in sorted order and
--   checking every cap against settled + outstanding amounts.
-- * The worker CLAIMs (RESERVED -> CLAIMED, lease) and marks EXECUTING in a
--   committed write BEFORE contacting the provider; no transaction is open
--   during the provider call.
-- * SETTLE records the cost state: CONFIRMED / CONFIRMED_ZERO / ESTIMATED with
--   actual_usd, or UNKNOWN with actual_usd NULL -- an UNKNOWN reservation keeps
--   holding its full quoted amount until RECONCILE resolves it with evidence.
-- * An expired EXECUTING lease becomes UNKNOWN (never released, never
--   replayed). Only RESERVED/CLAIMED (provider certainly not contacted) can be
--   RELEASED automatically.
-- Amount counted against every scope of a reservation:
--   RELEASED -> 0; SETTLED -> actual_usd; anything else (incl. UNKNOWN) -> quoted_usd.
-- The rolling-24 h ("daily") scope counts settled reservations by reserved_at
-- within 24 h, and every unsettled reservation regardless of age.

-- Lock anchors: one row per budget scope. Financial transactions lock these
-- rows (never an aggregate) in ascending `scope` order.
CREATE TABLE IF NOT EXISTS intake_budget_scopes (
    scope       TEXT PRIMARY KEY CHECK (length(scope) <= 300),
    kind        TEXT NOT NULL CHECK (kind IN ('project', 'daily', 'campaign')),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS intake_reservations (
    id                  TEXT PRIMARY KEY,
    idempotency_key     TEXT NOT NULL UNIQUE CHECK (length(idempotency_key) <= 300),
    account_id          TEXT NOT NULL,
    project_id          TEXT NOT NULL,
    lane                TEXT NOT NULL CHECK (lane IN ('production', 'campaign')),
    campaign_id         TEXT,
    quoted_usd          NUMERIC(18, 8) NOT NULL CHECK (quoted_usd > 0),
    quote               JSONB NOT NULL,          -- envelope: routes, token bounds, prices, versions, caps snapshot
    state               TEXT NOT NULL CHECK (state IN
                            ('RESERVED', 'CLAIMED', 'EXECUTING', 'SETTLED', 'UNKNOWN', 'RELEASED')),
    cost_state          TEXT CHECK (cost_state IN ('CONFIRMED', 'CONFIRMED_ZERO', 'ESTIMATED', 'UNKNOWN')),
    actual_usd          NUMERIC(18, 8) CHECK (actual_usd IS NULL OR actual_usd >= 0),
    failure_reason      TEXT,
    claim_token         TEXT,
    claimed_by          TEXT,
    lease_expires_at    TIMESTAMPTZ,
    provider            TEXT,
    model               TEXT,
    provider_request_id TEXT,
    result              JSONB,                   -- validated-later raw interpretation (no secrets)
    reserved_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    claimed_at          TIMESTAMPTZ,
    executing_at        TIMESTAMPTZ,
    settled_at          TIMESTAMPTZ,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT intake_res_lane_campaign CHECK ((lane = 'campaign') = (campaign_id IS NOT NULL)),
    CONSTRAINT intake_res_settled_cost CHECK (
        (state = 'SETTLED' AND cost_state IN ('CONFIRMED', 'CONFIRMED_ZERO', 'ESTIMATED') AND actual_usd IS NOT NULL)
        OR (state = 'UNKNOWN' AND cost_state = 'UNKNOWN' AND actual_usd IS NULL AND failure_reason IS NOT NULL)
        OR (state IN ('RESERVED', 'CLAIMED', 'EXECUTING', 'RELEASED') AND cost_state IS NULL AND actual_usd IS NULL)),
    CONSTRAINT intake_res_zero CHECK (cost_state <> 'CONFIRMED_ZERO' OR actual_usd = 0),
    CONSTRAINT intake_res_claim CHECK (state NOT IN ('CLAIMED', 'EXECUTING') OR
                                       (claim_token IS NOT NULL AND lease_expires_at IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS idx_intake_res_project ON intake_reservations(account_id, project_id, reserved_at DESC);
CREATE INDEX IF NOT EXISTS idx_intake_res_open ON intake_reservations(state, lease_expires_at)
    WHERE state IN ('RESERVED', 'CLAIMED', 'EXECUTING', 'UNKNOWN');

CREATE TABLE IF NOT EXISTS intake_reservation_scopes (
    reservation_id  TEXT NOT NULL REFERENCES intake_reservations(id),
    scope           TEXT NOT NULL REFERENCES intake_budget_scopes(scope),
    cap_usd         NUMERIC(18, 8) NOT NULL CHECK (cap_usd >= 0),   -- cap in force when reserved (audit)
    PRIMARY KEY (reservation_id, scope)
);
CREATE INDEX IF NOT EXISTS idx_intake_res_scopes_scope ON intake_reservation_scopes(scope, reservation_id);

-- Transactional outbox: written in the RESERVE transaction; relayed to RQ with
-- job id = reservation id (duplicate delivery is harmless: CLAIM is atomic).
CREATE TABLE IF NOT EXISTS intake_outbox (
    id              BIGSERIAL PRIMARY KEY,
    reservation_id  TEXT NOT NULL UNIQUE REFERENCES intake_reservations(id),
    payload         JSONB NOT NULL,
    enqueued_at     TIMESTAMPTZ,
    deliveries      INTEGER NOT NULL DEFAULT 0 CHECK (deliveries >= 0),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_intake_outbox_pending ON intake_outbox(id) WHERE enqueued_at IS NULL;

-- Append-only audit of every state change.
CREATE TABLE IF NOT EXISTS intake_reservation_events (
    id              BIGSERIAL PRIMARY KEY,
    reservation_id  TEXT NOT NULL REFERENCES intake_reservations(id),
    from_state      TEXT,
    to_state        TEXT NOT NULL,
    detail          JSONB NOT NULL DEFAULT '{}'::jsonb,
    at              TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_intake_res_events ON intake_reservation_events(reservation_id, id);

-- Conversation messages may now carry an UNKNOWN cost (NULL) and point at
-- their reservation. Existing rows keep their values.
ALTER TABLE intake_messages ADD COLUMN IF NOT EXISTS reservation_id TEXT;
ALTER TABLE intake_messages ADD COLUMN IF NOT EXISTS cost_state TEXT;
ALTER TABLE intake_messages ALTER COLUMN cost_usd DROP NOT NULL;

-- END SOURCE 037_intake_budget_reservations.sql

