INSERT INTO schema_migrations(version, name, sha256)
VALUES (29, 'internal_entitlements', encode(sha256(convert_to($source_029$-- Internal entitlements and reservation funding source (migration 029).
-- Founder decision 2026-10-07 (#24): internal QA funding is an explicit,
-- audited entitlement bound to an account id and an environment scope, never
-- an implicit email match, and its budget is separate from the customer plan.
--
-- Only INTERNAL_QA in the staging scope exists. Adding another entitlement or
-- scope (for example production) is a deliberate schema change, not a row.
-- Revocation keeps the row (audit trail); at most one active grant per
-- (account, entitlement, environment).

CREATE TABLE IF NOT EXISTS internal_entitlements (
    id              TEXT PRIMARY KEY,
    account_id      TEXT NOT NULL REFERENCES creator_accounts(id),
    entitlement     TEXT NOT NULL CHECK (entitlement IN ('INTERNAL_QA')),
    environment     TEXT NOT NULL CHECK (environment IN ('staging')),
    reason          TEXT NOT NULL CHECK (length(trim(reason)) > 0),
    granted_by      TEXT NOT NULL CHECK (length(trim(granted_by)) > 0),
    granted_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    revoked_at      TIMESTAMPTZ,
    revoked_by      TEXT,
    revoke_reason   TEXT,
    CONSTRAINT internal_entitlements_revocation CHECK ((revoked_at IS NULL) = (revoked_by IS NULL))
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_internal_entitlements_active
    ON internal_entitlements(account_id, entitlement, environment)
    WHERE revoked_at IS NULL;

-- Which budget funded a reservation. Customer-plan reservations move the
-- account's plan counters; internal QA reservations never do, and only they
-- count against the internal QA caps.
ALTER TABLE credit_reservations
    ADD COLUMN IF NOT EXISTS funding_source TEXT NOT NULL DEFAULT 'customer_plan'
        CHECK (funding_source IN ('customer_plan', 'internal_qa'));

CREATE INDEX IF NOT EXISTS idx_credit_reservations_internal_qa
    ON credit_reservations(created_at)
    WHERE funding_source = 'internal_qa';
$source_029$, 'UTF8')), 'hex'));

INSERT INTO schema_migrations(version, name, sha256)
VALUES (30, 'project_briefs_and_approvals', encode(sha256(convert_to($source_030$-- Discovery brief and server-bound build approval (migration 030).
-- Master directive 2026-10-09 §4-5.
--
-- project_briefs: every change to the discovery answers is a new immutable
-- revision. Writers use compare-and-set on the revision number (the UNIQUE
-- constraint makes a lost race fail instead of overwriting).
--
-- build_approvals: "approve and start building" binds the user, project,
-- brief revision + fingerprint, build contract + fingerprint and the budget
-- quote (budget revision) for a limited time. A build consumes exactly one
-- ACTIVE approval; a newer brief revision or a different quote makes it stale.

CREATE TABLE IF NOT EXISTS project_briefs (
    id           TEXT PRIMARY KEY,
    project_id   TEXT NOT NULL REFERENCES creator_projects(id) ON DELETE CASCADE,
    revision     INTEGER NOT NULL CHECK (revision > 0),
    account_id   TEXT NOT NULL REFERENCES creator_accounts(id),
    mode         TEXT NOT NULL CHECK (mode IN ('guided', 'recommend')),
    complete     BOOLEAN NOT NULL,
    brief_json   JSONB NOT NULL,
    fingerprint  TEXT NOT NULL,
    request_key  TEXT,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (project_id, revision)
);
-- A retried submission (same idempotency key) returns the revision it made.
CREATE UNIQUE INDEX IF NOT EXISTS uq_project_briefs_request_key
    ON project_briefs(project_id, request_key) WHERE request_key IS NOT NULL;

CREATE OR REPLACE FUNCTION reject_project_brief_mutation()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION 'project briefs are immutable; write a new revision';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_project_briefs_immutable ON project_briefs;
CREATE TRIGGER trg_project_briefs_immutable
BEFORE UPDATE ON project_briefs
FOR EACH ROW EXECUTE FUNCTION reject_project_brief_mutation();

CREATE TABLE IF NOT EXISTS build_approvals (
    id                    TEXT PRIMARY KEY,
    project_id            TEXT NOT NULL REFERENCES creator_projects(id) ON DELETE CASCADE,
    account_id            TEXT NOT NULL REFERENCES creator_accounts(id),
    brief_id              TEXT NOT NULL REFERENCES project_briefs(id),
    brief_revision        INTEGER NOT NULL,
    brief_fingerprint     TEXT NOT NULL,
    build_contract_id     TEXT NOT NULL REFERENCES m5_build_contracts(id),
    contract_fingerprint  TEXT NOT NULL,
    budget_fingerprint    TEXT NOT NULL,
    status                TEXT NOT NULL CHECK (status IN ('ACTIVE', 'USED', 'INVALIDATED', 'EXPIRED')),
    expires_at            TIMESTAMPTZ NOT NULL,
    used_by_build_id      TEXT,
    invalidated_reason    TEXT,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT build_approvals_used CHECK ((status = 'USED') = (used_by_build_id IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS idx_build_approvals_project ON build_approvals(project_id, created_at DESC);
$source_030$, 'UTF8')), 'hex'));

INSERT INTO schema_migrations(version, name, sha256)
VALUES (31, 'build_cancel_and_events', encode(sha256(convert_to($source_031$-- Stop a build and show what it is doing; preview data durability (migration 031).
-- Master directive 2026-10-09 §10 (task states, cancel) and §12 (the user
-- always sees what is happening).
--
-- cancel_requested_at: set by the owner's "stop" on a RUNNING build. The
-- worker checks it before every model call and every sandbox run, stops
-- there, settles only what was really used and writes CANCELLED. A QUEUED
-- build is cancelled directly by the API (the worker's QUEUED -> RUNNING
-- claim then fails, so it never starts).
--
-- build_events: an append-only, human-readable log of the build's steps
-- (phase changes, model calls by task, test runs and their result). It is
-- what the workspace shows as the live log. Messages never contain secrets
-- or generated code; they are short sentences written by the worker.

ALTER TABLE build_jobs ADD COLUMN IF NOT EXISTS cancel_requested_at TIMESTAMPTZ;
ALTER TABLE build_jobs ADD COLUMN IF NOT EXISTS cancel_requested_by TEXT;

CREATE TABLE IF NOT EXISTS build_events (
    seq        BIGSERIAL PRIMARY KEY,
    build_id   TEXT NOT NULL REFERENCES build_jobs(id) ON DELETE CASCADE,
    at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    kind       TEXT NOT NULL CHECK (kind IN ('phase', 'model', 'check', 'repair', 'cancel', 'info')),
    message    TEXT NOT NULL CHECK (length(message) <= 600)
);

CREATE INDEX IF NOT EXISTS idx_build_events_build_seq ON build_events (build_id, seq);

-- Directive §13: whether a preview's product data survives a restart and a
-- new version ('persistent', one directory per project on the preview host)
-- or lives only in the container's tmpfs ('temporary'). NULL = before 031.
ALTER TABLE project_previews ADD COLUMN IF NOT EXISTS data_storage TEXT
    CHECK (data_storage IS NULL OR data_storage IN ('persistent', 'temporary'));
$source_031$, 'UTF8')), 'hex'));

INSERT INTO schema_migrations(version, name, sha256)
VALUES (32, 'preview_access', encode(sha256(convert_to($source_032$-- Private previews (migration 032). Autonomous completion directive §4.
--
-- Real-server finding 2026-10-09: preview hostnames are published in
-- certificate-transparency logs (on-demand TLS), and internet scanners hit
-- them within minutes. An unguessable URL is not access control.
--
-- access_mode: PRIVATE (default; only holders of an owner token), SHARED
-- (owner tokens + share tokens the owner created), PUBLIC (anyone). Existing
-- rows become PRIVATE.
--
-- preview_access_tokens: random tokens, stored only as SHA-256; issued by the
-- API to the authenticated owner (short-lived) or as a share link; checked by
-- the preview router on the host; revocable; usage counted for audit.
-- preview_access_audit: issued / revoked / mode changes and refused requests
-- (aggregated per preview and minute), never the token itself.

ALTER TABLE project_previews ADD COLUMN IF NOT EXISTS access_mode TEXT NOT NULL DEFAULT 'PRIVATE'
    CHECK (access_mode IN ('PRIVATE', 'SHARED', 'PUBLIC'));

CREATE TABLE IF NOT EXISTS preview_access_tokens (
    token_hash   TEXT PRIMARY KEY,
    preview_id   TEXT NOT NULL REFERENCES project_previews(id) ON DELETE CASCADE,
    kind         TEXT NOT NULL CHECK (kind IN ('owner', 'share')),
    issued_to    TEXT,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at   TIMESTAMPTZ NOT NULL,
    revoked_at   TIMESTAMPTZ,
    last_used_at TIMESTAMPTZ,
    uses         INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_preview_access_tokens_preview ON preview_access_tokens (preview_id);

CREATE TABLE IF NOT EXISTS preview_access_audit (
    id         BIGSERIAL PRIMARY KEY,
    preview_id TEXT NOT NULL,
    at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    event      TEXT NOT NULL CHECK (event IN ('issued', 'revoked', 'mode', 'denied')),
    detail     TEXT NOT NULL DEFAULT '' CHECK (length(detail) <= 300)
);

CREATE INDEX IF NOT EXISTS idx_preview_access_audit_preview ON preview_access_audit (preview_id, at);
$source_032$, 'UTF8')), 'hex'));

INSERT INTO schema_migrations(version, name, sha256)
VALUES (33, 'recovery_and_change_parity', encode(sha256(convert_to($source_033$-- Crash recovery and change (modification) parity (migration 033).
-- Autonomous completion directive §5.
--
-- heartbeat_at: written by the worker at every step boundary (before each
-- model call and each sandbox run). A RUNNING job whose heartbeat is older
-- than the recovery limit lost its worker (crash, OOM, host restart); the
-- janitor puts it back in the queue once (recovery_attempts) and fails it
-- after that, releasing its reservation. A stop request on such a job ends
-- it CANCELLED instead.
--
-- Changes get the same stop flag, heartbeat and live log as builds:
-- build_events now carries both kinds (job_kind); the foreign key to
-- build_jobs is dropped so a change's id can be logged (ownership is checked
-- by the API through the owning table).

ALTER TABLE build_jobs ADD COLUMN IF NOT EXISTS heartbeat_at TIMESTAMPTZ;
ALTER TABLE build_jobs ADD COLUMN IF NOT EXISTS recovery_attempts INTEGER NOT NULL DEFAULT 0;

ALTER TABLE modification_requests ADD COLUMN IF NOT EXISTS cancel_requested_at TIMESTAMPTZ;
ALTER TABLE modification_requests ADD COLUMN IF NOT EXISTS heartbeat_at TIMESTAMPTZ;
ALTER TABLE modification_requests ADD COLUMN IF NOT EXISTS recovery_attempts INTEGER NOT NULL DEFAULT 0;
ALTER TABLE modification_requests DROP CONSTRAINT IF EXISTS modification_requests_status_check;
ALTER TABLE modification_requests ADD CONSTRAINT modification_requests_status_check CHECK (status IN (
    'QUEUED', 'RUNNING', 'NEEDS_CLARIFICATION', 'READY_FOR_REVIEW',
    'ACCEPTED', 'REJECTED', 'FAILED', 'CONFLICT', 'CANCELLED'
));

ALTER TABLE build_events DROP CONSTRAINT IF EXISTS build_events_build_id_fkey;
ALTER TABLE build_events ADD COLUMN IF NOT EXISTS job_kind TEXT NOT NULL DEFAULT 'build'
    CHECK (job_kind IN ('build', 'modification'));
$source_033$, 'UTF8')), 'hex'));

INSERT INTO schema_migrations(version, name, sha256)
VALUES (34, 'agent_runtime', encode(sha256(convert_to($source_034$-- Durable agent execution (migration 034). Autonomous completion directive §12.
--
-- agent_runs: one task graph per build or change.
-- agent_tasks: one row per agent task; state machine enforced by the runtime
--   (PENDING, READY, RUNNING, WAITING, BLOCKED, VERIFYING, REPAIRING,
--    SUCCEEDED, FAILED, CANCEL_REQUESTED, CANCELLED); survives restarts.
--   verified_by_task points at the independent verifier's task.
-- agent_handoffs: structured handoffs between agents (payload refs only).
-- agent_memory: per-project, per-agent facts (no secrets).
-- platform_check_results: results of real-server golden/post-deploy checks,
--   the evidence the capability auditor and the quality gate read.

CREATE TABLE IF NOT EXISTS agent_runs (
    id           TEXT PRIMARY KEY,
    subject_kind TEXT NOT NULL CHECK (subject_kind IN ('build', 'modification', 'check')),
    subject_id   TEXT NOT NULL,
    budget_usd   NUMERIC(12, 6),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    finished_at  TIMESTAMPTZ,
    outcome      TEXT
);
CREATE INDEX IF NOT EXISTS idx_agent_runs_subject ON agent_runs (subject_kind, subject_id);

CREATE TABLE IF NOT EXISTS agent_tasks (
    id               TEXT PRIMARY KEY,
    run_id           TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,
    agent_key        TEXT NOT NULL,
    skill_keys       JSONB NOT NULL DEFAULT '[]'::jsonb,
    state            TEXT NOT NULL CHECK (state IN ('PENDING', 'READY', 'RUNNING', 'WAITING', 'BLOCKED', 'VERIFYING',
                                                     'REPAIRING', 'SUCCEEDED', 'FAILED', 'CANCEL_REQUESTED', 'CANCELLED')),
    depends_on       JSONB NOT NULL DEFAULT '[]'::jsonb,
    attempt          INTEGER NOT NULL DEFAULT 1,
    budget_usd       NUMERIC(12, 6),
    cost_usd         NUMERIC(12, 6) NOT NULL DEFAULT 0,
    verified_by_task TEXT,
    evidence         JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    started_at       TIMESTAMPTZ,
    finished_at      TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_agent_tasks_run ON agent_tasks (run_id);
CREATE INDEX IF NOT EXISTS idx_agent_tasks_agent ON agent_tasks (agent_key, finished_at);

CREATE TABLE IF NOT EXISTS agent_handoffs (
    id         BIGSERIAL PRIMARY KEY,
    run_id     TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,
    from_task  TEXT NOT NULL,
    to_agent   TEXT NOT NULL,
    payload    JSONB NOT NULL DEFAULT '{}'::jsonb,
    at         TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS agent_memory (
    project_id TEXT NOT NULL,
    agent_key  TEXT NOT NULL,
    key        TEXT NOT NULL,
    value      JSONB NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (project_id, agent_key, key)
);

CREATE TABLE IF NOT EXISTS platform_check_results (
    id         BIGSERIAL PRIMARY KEY,
    check_key  TEXT NOT NULL,
    stage      TEXT NOT NULL,
    passed     BOOLEAN NOT NULL,
    detail     TEXT NOT NULL DEFAULT '' CHECK (length(detail) <= 2000),
    commit_sha TEXT,
    at         TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_platform_check_results_key ON platform_check_results (check_key, at DESC);
$source_034$, 'UTF8')), 'hex'));

INSERT INTO schema_migrations(version, name, sha256)
VALUES (35, 'build_stage_results', encode(sha256(convert_to($source_035$-- Durable per-stage quality evidence (migration 035). Issue #6 P1, Production
-- Assurance v2 §5. Additive; rollback = DROP TABLE build_stage_results (nothing
-- else reads it).
--
-- One row per check of the release policy for one build: the checked artifact
-- digest, the policy version, who verified (platform module or model) and
-- whether that verifier is independent of the generating model. Rows are
-- immutable; a repeated write for the same (build, artifact, policy, check) is
-- a no-op, so a duplicate delivery or a recovered worker cannot change them.
-- A different artifact digest is a different row: evidence never transfers
-- from one repository state to another.

CREATE TABLE IF NOT EXISTS build_stage_results (
    id              BIGSERIAL PRIMARY KEY,
    build_id        TEXT NOT NULL,
    job_kind        TEXT NOT NULL DEFAULT 'build' CHECK (job_kind IN ('build', 'modification', 'replay')),
    tenant_key      TEXT,
    stage           TEXT NOT NULL,
    check_key       TEXT NOT NULL,
    status          TEXT NOT NULL CHECK (status IN ('PASS', 'FAIL', 'NOT_RUN', 'UNKNOWN', 'NOT_APPLICABLE')),
    required        BOOLEAN NOT NULL,
    verifier        TEXT NOT NULL,
    independent     BOOLEAN NOT NULL,
    severity        TEXT NOT NULL,
    detail          TEXT NOT NULL DEFAULT '' CHECK (length(detail) <= 1000),
    artifact_sha256 TEXT NOT NULL,
    policy_version  TEXT NOT NULL,
    report_schema   TEXT NOT NULL,
    decision        TEXT NOT NULL CHECK (decision IN ('READY', 'FAILED')),
    source_commit   TEXT,
    environment     TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (build_id, artifact_sha256, policy_version, check_key)
);
CREATE INDEX IF NOT EXISTS idx_build_stage_results_build ON build_stage_results (build_id);
CREATE INDEX IF NOT EXISTS idx_build_stage_results_check ON build_stage_results (check_key, status, created_at DESC);
$source_035$, 'UTF8')), 'hex'));

INSERT INTO schema_migrations(version, name, sha256)
VALUES (36, 'intelligence_plane', encode(sha256(convert_to($source_036$-- Wave A intelligence control plane (migration 036). Additive only; rollback =
-- DROP TABLE provider_health, intake_messages, execution_plans (no other table
-- references them).
--
-- provider_health: durable circuit breaker per model route (route name only;
--   never keys or request content). Read by every gateway before routing.
-- intake_messages: the customer's free-text intake conversation per project,
--   bound to the brief revision it produced. The brief (project_briefs) stays
--   the source of truth; these rows are the audit trail of how it changed.
-- execution_plans: the Chief Architect's validated plan + task DAG for one
--   brief revision (immutable; identified by its content fingerprint).

CREATE TABLE IF NOT EXISTS provider_health (
    route       TEXT PRIMARY KEY,
    state       TEXT NOT NULL CHECK (state IN ('HEALTHY', 'DEGRADED', 'RATE_LIMITED', 'CREDIT_EXHAUSTED', 'AUTH_INVALID',
                                               'UNAVAILABLE', 'RETIRED', 'UNKNOWN')),
    detail      TEXT NOT NULL DEFAULT '' CHECK (length(detail) <= 300),
    since       TIMESTAMPTZ,
    open_until  TIMESTAMPTZ,
    recheck_at  TIMESTAMPTZ,
    failures    INTEGER NOT NULL DEFAULT 0,
    reset_by    TEXT NOT NULL DEFAULT '',
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS intake_messages (
    id              BIGSERIAL PRIMARY KEY,
    project_id      TEXT NOT NULL,
    account_id      TEXT NOT NULL,
    role            TEXT NOT NULL CHECK (role IN ('customer', 'assistant')),
    content         TEXT NOT NULL CHECK (length(content) <= 8000),
    brief_revision  INTEGER,
    interpretation  JSONB NOT NULL DEFAULT '{}'::jsonb,
    interpreter     TEXT NOT NULL DEFAULT 'deterministic',
    cost_usd        NUMERIC(12, 6) NOT NULL DEFAULT 0,
    request_key     TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_intake_messages_project ON intake_messages (project_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_intake_messages_request
    ON intake_messages (project_id, request_key, role) WHERE request_key IS NOT NULL;

CREATE TABLE IF NOT EXISTS execution_plans (
    id                TEXT PRIMARY KEY,
    project_id        TEXT NOT NULL,
    brief_revision    INTEGER NOT NULL,
    brief_fingerprint TEXT NOT NULL,
    plan_schema       TEXT NOT NULL,
    fingerprint       TEXT NOT NULL,
    plan              JSONB NOT NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (project_id, fingerprint)
);
CREATE INDEX IF NOT EXISTS idx_execution_plans_project ON execution_plans (project_id, brief_revision);
